package com.hkdn.backend.service;

import com.hkdn.backend.entity.*;import com.hkdn.backend.exception.BusinessException;import com.hkdn.backend.repository.DigitalSignatureRepository;import com.hkdn.backend.repository.UserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.*;import java.util.*;

@Service public class DigitalSignatureService {
 private final DigitalSignatureRepository signatures; private final UserRepository users; private final String privateKeyBase64; private final String publicKeyBase64; private final String keyId;
 public DigitalSignatureService(DigitalSignatureRepository signatures,UserRepository users,@Value("${signature.private-key-base64:}") String privateKeyBase64,@Value("${signature.public-key-base64:}") String publicKeyBase64,@Value("${signature.key-id:educertify-default}") String keyId){this.signatures=signatures;this.users=users;this.privateKeyBase64=privateKeyBase64;this.publicKeyBase64=publicKeyBase64;this.keyId=keyId;}
 @Transactional public Optional<DigitalSignature> sign(String hash,UUID signerId){if(privateKeyBase64==null||privateKeyBase64.isBlank()||publicKeyBase64==null||publicKeyBase64.isBlank())return Optional.empty();try{PrivateKey privateKey=privateKey();Signature signer=Signature.getInstance("RSASSA-PSS");signer.setParameter(new java.security.spec.PSSParameterSpec("SHA-256","MGF1",java.security.spec.MGF1ParameterSpec.SHA256,32,1));signer.initSign(privateKey);signer.update(hash.getBytes(StandardCharsets.UTF_8));DigitalSignature entity=new DigitalSignature();entity.setAlgorithm("RSASSA-PSS-SHA256");entity.setKeyId(keyId);entity.setSigner(users.findById(signerId).orElseThrow());entity.setContentHash(hash);entity.setSignatureValue(Base64.getEncoder().encodeToString(signer.sign()));entity.setPublicKey(publicKeyBase64);return Optional.of(signatures.save(entity));}catch(GeneralSecurityException e){throw new BusinessException("Unable to create digital signature");}}
 public boolean verify(DigitalSignature stored,String hash){if(stored==null||!stored.isValid()||!stored.getContentHash().equalsIgnoreCase(hash))return false;try{byte[] key=Base64.getDecoder().decode(stored.getPublicKey());PublicKey publicKey=KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(key));Signature verifier=Signature.getInstance("RSASSA-PSS");verifier.setParameter(new java.security.spec.PSSParameterSpec("SHA-256","MGF1",java.security.spec.MGF1ParameterSpec.SHA256,32,1));verifier.initVerify(publicKey);verifier.update(hash.getBytes(StandardCharsets.UTF_8));return verifier.verify(Base64.getDecoder().decode(stored.getSignatureValue()));}catch(GeneralSecurityException|IllegalArgumentException e){return false;}}
 private PrivateKey privateKey() throws GeneralSecurityException{byte[] key=Base64.getDecoder().decode(privateKeyBase64);return KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(key));}
}
